### Edit 3 — Modify `handlePaymentIntentStatusChange` to add SAGA logic

Find the existing `handlePaymentIntentStatusChange` function. Add `eventType: string` as a parameter. Update the call site in `processStripeEvent` to pass `event.type`.

After the existing `stripe_charge_update_status_from_webhook` RPC call inside the handler, add:

```ts
const depositTxnId = pi.metadata?.inkos_deposit_transaction_id;

if (eventType === 'payment_intent.succeeded') {
  // SAGA step 2 — confirm deposit
  if (depositTxnId && depositTxnId.length > 0) {
    const { error: confirmErr } = await supabase.rpc(RPC.CONFIRM_DEPOSIT_APPLICATION, {
      p_transaction_id: depositTxnId,
      p_payment_intent_id: pi.id,
    });
    if (confirmErr) {
      logger.error({ pi_id: pi.id, deposit_txn: depositTxnId, err: confirmErr },
        'CRITICAL: confirm_deposit_application failed on PI succeeded');
      throw confirmErr;
    }
  }

  // Write commission_splits row from PI metadata
  const studioId = pi.metadata?.inkos_studio_id;
  const artistId = pi.metadata?.inkos_artist_id;
  const bookingId = pi.metadata?.inkos_booking_id;
  const sessionId = pi.metadata?.inkos_session_id;
  if (studioId && artistId && bookingId) {
    // §S13.3 — types.ts regen pending; cast for stripe_charges read
    const fromUntyped = supabase.from as unknown as (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          single: () => Promise<{ data: Record<string, unknown> | null; error: unknown }>;
        };
      };
    };
    const { data: chargeData } = await fromUntyped('stripe_charges')
      .select('net_artist_cents, application_fee_cents, tip_amount_cents, deposit_drawdown_cents, transfer_id')
      .eq('payment_intent_id', pi.id)
      .single();

    if (chargeData) {
      const charge = chargeData as {
        net_artist_cents: number;
        application_fee_cents: number;
        tip_amount_cents: number;
        deposit_drawdown_cents: number;
        transfer_id: string | null;
      };
      const totalArtistShare = charge.net_artist_cents + charge.application_fee_cents;
      const commissionPct = totalArtistShare > 0
        ? Math.round((charge.net_artist_cents / totalArtistShare) * 100)
        : 100;

      const { error: splitErr } = await supabase.rpc(RPC.COMMISSION_SPLIT_RECORD, {
        p_studio_id: studioId,
        p_booking_id: bookingId,
        p_session_id: sessionId ?? null,
        p_artist_id: artistId,
        p_base_amount_cents: charge.net_artist_cents,
        p_commission_pct: commissionPct,
        p_tip_amount_cents: charge.tip_amount_cents,
        p_applied_from_pool_cents: charge.deposit_drawdown_cents,
        p_stripe_transfer_id: charge.transfer_id,
        p_kind: 'split',
      });
      if (splitErr) {
        logger.error({ pi_id: pi.id, err: splitErr },
          'commission_split_record failed on PI succeeded — recoverable via reconciliation cron');
        // Don't throw — reconciliation cron will catch this
      }
    }
  }
}

if (eventType === 'payment_intent.payment_failed' || eventType === 'payment_intent.canceled') {
  // SAGA step 2 — rollback deposit
  if (depositTxnId && depositTxnId.length > 0) {
    const reason = eventType === 'payment_intent.canceled' ? 'payment_canceled' : 'payment_failed';
    const { error: rollbackErr } = await supabase.rpc(RPC.ROLLBACK_DEPOSIT_APPLICATION, {
      p_transaction_id: depositTxnId,
      p_reason: reason,
    });
    if (rollbackErr) {
      logger.error({ pi_id: pi.id, deposit_txn: depositTxnId, err: rollbackErr },
        'CRITICAL: rollback_deposit_application failed on PI failed/canceled');
      throw rollbackErr;
    }
  }
}
```

### Edit 4 — Add `charge.refunded` handler

Add a new case in the switch statement in `processStripeEvent` (or wherever the switch lives):

```ts
